function parseBatch(text,format='auto'){text=text.replace(/^\uFEFF/,'').trim();if(!text)return [];if(format==='auto'){if(/^[\[{]/.test(text))format='json';else if(text.includes('\t'))format='tsv';else if(/^(username|user|name|ชื่อ)[,;]/i.test(text))format='csv';else format='lines'}let rows=[];if(format==='json'){let data=JSON.parse(text);if(!Array.isArray(data))data=data.comments;if(!Array.isArray(data))throw Error('JSON ต้องเป็น array หรือ {comments: []}');rows=data.map(x=>typeof x==='string'?{name:'',text:x}:{name:String(x.username??x.name??''),text:String(x.comment??x.text??'')})}else if(format==='csv'||format==='tsv'){let a=delimited(text,format==='tsv'?'\t':',');if(a.length&&/^(username|user|name|ชื่อ)$/i.test(a[0][0].trim()))a.shift();rows=a.map(r=>({name:r.length>1?r[0]:'',text:r.length>1?r.slice(1).join(format==='tsv'?'\t':','):r[0]}))}else{rows=text.split(/\r?\n/).map(line=>{let s=line.trim().replace(/^[-•]\s+/,'').replace(/^\d+[.)]\s+/,'');let m=s.match(/^(@[^\s:：]+)\s*[:：]?\s+(.+)$/u)||s.match(/^([^:：]{1,60})\s*[:：]\s*(.+)$/u);return m?{name:m[1].trim(),text:m[2]}:{name:'',text:s}})}return rows.map(r=>({name:r.name.trim().slice(0,80),text:r.text.trim().slice(0,1000)})).filter(r=>r.text)}
function updateBatch(){let el=$('batchPreview');el.replaceChildren();try{let rows=parseBatch($('batchText').value,$('batchFormat').value);$('batchCount').textContent=rows.length+' รายการ (สูงสุด 60)';for(let [i,r] of rows.slice(0,60).entries()){let b=document.createElement('div');b.className='batchitem';let n=document.createElement('b');n.textContent=r.name||`Q${String(i+1).padStart(2,'0')}`;let t=document.createElement('div');t.textContent=r.text;b.append(n,t);el.append(b)}$('batchGenerate').disabled=!rows.length||rows.length>60;return rows}catch(e){$('batchCount').textContent=e.message;$('batchGenerate').disabled=true;return []}}
$('batchOpen').onclick=()=>{$('batchDialog').showModal();updateBatch()};$('batchClose').onclick=()=>$('batchDialog').close();$('batchText').oninput=updateBatch;$('batchFormat').onchange=updateBatch;$('batchImport').onclick=()=>{$('batchFile').value='';$('batchFile').click()};$('batchFile').onchange=async()=>{let f=$('batchFile').files[0];if(!f)return;if(f.size>2*1024*1024){$('batchCount').textContent='ไฟล์ใหญ่เกิน 2 MB';return}$('batchText').value=await f.text();let ext=f.name.split('.').pop().toLowerCase();$('batchFormat').value=['csv','tsv','json'].includes(ext)?ext:'auto';updateBatch()};
$('batchGenerate').onclick=()=>{let rows=updateBatch();if(!rows.length||rows.length>60)return;if($('batchReal').checked&&rows.some(r=>!r.name)){$('batchCount').textContent='คอมเมนต์จริงต้องมี Username ทุกรายการ';return}remember();if($('batchReplace').checked)state.objects=state.objects.filter(o=>o.kind!=='comment');for(let r of rows){let o=makeComment(r.text,r.name,$('batchReal').checked?'real':'mock');state.objects.push(o);selected=o.id}for(let l of logos())if(l.scope==='one'&&!comments().some(o=>o.id===l.target))l.target=comments()[0]?.id||'';$('batchDialog').close();selectMode('multi');arrange(state.layout||'stack',false);revealCommentEditor();status(`สร้าง ${rows.length} คอมเมนต์แล้ว`)};
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
const date=()=>new Date().toISOString().slice(0,10), filename=(s)=>String(s).replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,50)||'comment';
$('saveProject').onclick=()=>{download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),`SCComment_${date()}.json`);status('บันทึกโปรเจกต์แล้ว')};$('loadProject').onclick=()=>{$('projectFile').value='';$('projectFile').click()};
function validateProject(p){if(!p||p.version!==2||!Number.isInteger(p.w)||!Number.isInteger(p.h)||p.w<100||p.h<100||p.w>4096||p.h>4096||!Array.isArray(p.objects)||p.objects.length>300||!p.bg)throw Error('ไฟล์โปรเจกต์ไม่ถูกต้อง');let ids=new Set();function asset(v){if(v&&(!/^data:image\/(png|jpeg|webp|gif|svg\+xml);base64,/i.test(v)||v.length>22*1024*1024))throw Error('รูปภาพในโปรเจกต์ไม่รองรับ')}
for(let o of p.objects){if(!['comment','image','logo'].includes(o.kind)||typeof o.id!=='string'||ids.has(o.id)||!['x','y','w','h','rotation','opacity'].every(k=>Number.isFinite(o[k]))||o.w<=0||o.h<=0||o.w>20000||o.h>20000||Math.abs(o.x)>30000||Math.abs(o.y)>30000||o.opacity<0||o.opacity>100)throw Error('ข้อมูล Layer ไม่ถูกต้อง');ids.add(o.id);asset(o.src);asset(o.photo);if(o.kind==='comment'&&(typeof o.comment!=='string'||typeof o.username!=='string'||o.comment.length>1000||o.username.length>80||!['mock','real'].includes(o.source)||!['light','dark'].includes(o.theme)||!['reply','normal'].includes(o.type)||!['auto','abstract','initial','illustration','default'].includes(o.avatarStyle)||typeof o.avatarSeed!=='string'||!Number.isFinite(o.fontSize)||o.fontSize<25||o.fontSize>62||![400,600,700].includes(o.fontWeight)))throw Error('ข้อมูล Comment ไม่ถูกต้อง');if(o.kind==='logo'&&(!['canvas','all','one'].includes(o.scope)||!Number.isInteger(o.anchor)||o.anchor<0||o.anchor>8||!Number.isFinite(o.ratio)||o.ratio<=0||!Number.isFinite(o.size)||o.size<5||o.size>90||!Number.isFinite(o.margin)||o.margin<0||o.margin>20))throw Error('ข้อมูล Logo ไม่ถูกต้อง')}
asset(p.bg.src);if(!['transparent','color','image'].includes(p.bg.type)||!/^#[a-f0-9]{6}$/i.test(p.bg.color)||!['cover','contain'].includes(p.bg.fit)||!Number.isFinite(p.bg.opacity)||p.bg.opacity<0||p.bg.opacity>100||!Number.isFinite(p.bg.blur)||p.bg.blur<0||p.bg.blur>60||!Number.isFinite(p.spacing)||p.spacing<0||p.spacing>100)throw Error('ข้อมูลพื้นหลังไม่ถูกต้อง');return p}
$('projectFile').onchange=async()=>{let f=$('projectFile').files[0];if(!f)return;try{if(f.size>100*1024*1024)throw Error('ไฟล์เกิน 100 MB');let p=validateProject(JSON.parse(await f.text()));remember();state={...defaults(),...p};selected=state.objects.at(-1)?.id||null;selectMode('multi');status('เปิดโปรเจกต์แล้ว')}catch(e){status(e.message,true)}};
const presetKey='sccomment-v2-presets';function getPresets(){try{return JSON.parse(localStorage.getItem(presetKey)||'[]')}catch{return []}}function presetUI(){let s=$('presetList'),v=s.value;s.replaceChildren(new Option('—',''));for(let p of getPresets())s.add(new Option(p.name,p.name));s.value=v}
$('savePreset').onclick=()=>{let name=prompt('ชื่อ Brand Preset','SCWork Q&A');if(!name?.trim())return;try{let all=getPresets().filter(p=>p.name!==name.trim());all.push({name:name.trim(),w:state.w,h:state.h,bg:clone(state.bg),logos:clone(logos()),spacing:state.spacing});localStorage.setItem(presetKey,JSON.stringify(all));presetUI();$('presetList').value=name.trim();status('บันทึก Brand Preset แล้ว')}catch(e){status('พื้นที่เก็บข้อมูลเบราว์เซอร์ไม่พอ — ใช้ Save project แทน',true)}};
$('loadPreset').onclick=()=>{let p=getPresets().find(x=>x.name===$('presetList').value);if(!p)return;remember();let sx=p.w/state.w,sy=p.h/state.h,k=Math.min(sx,sy);state.objects=state.objects.filter(o=>o.kind!=='logo');for(let o of state.objects){o.x*=sx;o.y*=sy;o.w*=k;o.h*=k}state.w=p.w;state.h=p.h;state.bg=clone(p.bg);state.spacing=p.spacing;for(let l of clone(p.logos)){l.id=uid();if(l.scope==='one')l.target=comments()[0]?.id||'';state.objects.push(l)}anchoredLogos();selected=state.objects.at(-1)?.id||null;selectMode('multi');status('ใช้ Brand Preset แล้ว')};$('removePreset').onclick=()=>{try{localStorage.setItem(presetKey,JSON.stringify(getPresets().filter(x=>x.name!==$('presetList').value)));presetUI()}catch(e){status('ลบ Preset ไม่สำเร็จ',true)}};
$('newProject').onclick=()=>{if(!confirm('เริ่มโปรเจกต์ใหม่จาก Default Template? บันทึกงานเดิมก่อนหากต้องการเก็บไว้'))return;applyTemplate(getDefaultTemplate(),false)};
function cardCanvas(o,scale){let m=metrics(o);if(640*scale*m.H*scale>32e6)throw Error('คอมเมนต์ยาวเกินสำหรับความละเอียดนี้');let c=document.createElement('canvas');c.width=640*scale;c.height=Math.ceil(m.H*scale);let ctx=c.getContext('2d');ctx.scale(scale,scale);card(ctx,o);drawLogoOnCard(ctx,o,640,m.H,o.id);return c}
function compCanvas(scale,kind){if(state.w*state.h*scale*scale>32e6||Math.max(state.w,state.h)*scale>8192)throw Error('ความละเอียดสูงเกินไป กรุณาลด Export scale');let c=document.createElement('canvas');c.width=state.w*scale;c.height=state.h*scale;let ctx=c.getContext('2d');ctx.scale(scale,scale);drawComposition(ctx,{transparent:kind==='transparent',jpg:kind==='jpg'});return c}
function blobOf(c,type='image/png'){return new Promise((r,j)=>c.toBlob(b=>b?r(b):j(Error('Export ไม่สำเร็จ')),type,.94))}
// Dependency-free ZIP (STORE), UTF-8 filenames and CRC-32.
const crcTable=Array.from({length:256},(_,i)=>{let c=i;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});function crc32(a){let c=0xffffffff;for(let x of a)c=crcTable[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0}
async function zipFiles(files){let local=[],central=[],off=0,clen=0;for(let f of files){let n=new TextEncoder().encode(f.name),d=new Uint8Array(await f.blob.arrayBuffer()),crc=crc32(d),a=new Uint8Array(30+n.length),v=new DataView(a.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,d.length,true);v.setUint32(22,d.length,true);v.setUint16(26,n.length,true);a.set(n,30);let b=new Uint8Array(46+n.length),w=new DataView(b.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint32(16,crc,true);w.setUint32(20,d.length,true);w.setUint32(24,d.length,true);w.setUint16(28,n.length,true);w.setUint32(42,off,true);b.set(n,46);local.push(a,d);central.push(b);off+=a.length+d.length;clen+=b.length}let end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,clen,true);v.setUint32(16,off,true);return new Blob([...local,...central,end],{type:'application/zip'})}
function exportTarget(){return current()?.kind==='comment'?current():comments()[0]}
function updateExport(){let t=$('exportType').value,s=num($('exportScale').value,1),o=exportTarget();let individual=['selected','zip'].includes(t);$('exportScale').options[2].disabled=!individual;if(!individual&&s===4){$('exportScale').value='2';s=2}let m=o?metrics(o):null;$('exportInfo').textContent=t==='zip'?`${comments().length} PNG files · ${640*s}px wide each`:t==='selected'?(m?`${640*s} × ${m.H*s} px`:'ไม่มีคอมเมนต์'):`${state.w*s} × ${state.h*s} px`;$('copyImage').disabled=t==='zip'||t==='jpg';$('exportGo').disabled=individual&&!o}
$('exportOpen').onclick=()=>{$('exportType').value=mode==='single'?'selected':(state.exportDefaults?.type||'png');$('exportScale').value=mode==='single'?'4':String(state.exportDefaults?.scale||1);updateExport();$('exportDialog').showModal();prepareShare()};$('exportType').onchange=$('exportScale').onchange=()=>{updateExport();prepareShare()};$('exportClose').onclick=()=>$('exportDialog').close();
async function produce(){await readyImages();let t=$('exportType').value,s=num($('exportScale').value,1),o=exportTarget();if(t==='selected'){if(!o)throw Error('ไม่มีคอมเมนต์');return {blob:await blobOf(cardCanvas(o,s)),name:`SCComment_${filename(o.username)}.png`}}if(t==='zip'){let files=[];for(let [i,o] of comments().entries()){let blob=await blobOf(cardCanvas(o,s));files.push({name:`${String(i+1).padStart(2,'0')}_${filename(o.username)}.png`,blob})}return {blob:await zipFiles(files),name:`SCComment_Batch_${date()}.zip`}}return {blob:await blobOf(compCanvas(s,t),t==='jpg'?'image/jpeg':'image/png'),name:`SCComment_Composition_${date()}.${t==='jpg'?'jpg':'png'}`}}

// Native file sharing must start inside the user's tap, not after asynchronous image rendering.
let preparedShare=null,shareToken=0,shareURL='';
function clearShare(){shareToken++;preparedShare=null;if(shareURL)URL.revokeObjectURL(shareURL);shareURL='';$('sharePreview').removeAttribute('src');$('sharePreviewWrap').hidden=true;$('shareImage').hidden=true;$('shareImage').disabled=true;$('shareInfo').textContent=''}
async function prepareShare(){clearShare();const token=shareToken,t=$('exportType').value;if(t==='zip'||(t==='selected'&&!exportTarget()))return;const supported=typeof navigator.share==='function'&&typeof navigator.canShare==='function';$('shareInfo').textContent=supported?'กำลังเตรียมภาพสำหรับ Share…':'ดาวน์โหลด หรือกดค้างที่ภาพเพื่อบันทึก (บนมือถือที่รองรับ)';try{const result=await produce();if(token!==shareToken||!$('exportDialog').open)return;preparedShare=new File([result.blob],result.name,{type:result.blob.type});shareURL=URL.createObjectURL(result.blob);$('sharePreview').src=shareURL;$('sharePreviewWrap').hidden=false;let can=false;try{can=supported&&navigator.canShare({files:[preparedShare]})}catch{}$('shareImage').hidden=!can;$('shareImage').disabled=!can;$('shareInfo').textContent=can?'แตะ Save to Photos / Share แล้วเลือก Save Image ในเมนู iOS หากมี':'ใช้ Download หรือกดค้างที่ภาพแล้วเลือกบันทึก หากเบราว์เซอร์รองรับ';}catch(e){if(token===shareToken)$('shareInfo').textContent='เตรียมภาพไม่สำเร็จ — '+e.message}}
$('exportDialog').addEventListener('close',clearShare);
$('shareImage').onclick=()=>{if(!preparedShare)return;let b=$('shareImage');b.disabled=true;try{const task=navigator.share({files:[preparedShare]});Promise.resolve(task).then(()=>{$('shareInfo').textContent='ส่งภาพไปยังเมนู Share แล้ว — ตรวจสอบใน Photos หากเลือก Save Image'}).catch(e=>{$('shareInfo').textContent=e.name==='AbortError'?'ยกเลิกการแชร์ — สามารถลองอีกครั้ง':'Share ไม่สำเร็จ — ใช้ Download หรือกดค้างที่ภาพ';}).finally(()=>{if($('exportDialog').open)b.disabled=!preparedShare});}catch(e){b.disabled=false;$('shareInfo').textContent='Share ไม่สำเร็จ — ใช้ Download หรือกดค้างที่ภาพ'}};

$('exportGo').onclick=async()=>{let b=$('exportGo');b.disabled=true;b.textContent='Exporting…';try{let f=await produce();download(f.blob,f.name);$('exportDialog').close();status('Export สำเร็จ')}catch(e){$('exportInfo').textContent=e.message;status(e.message,true)}finally{b.disabled=false;b.textContent='Download'}};
$('copyImage').onclick=async()=>{try{if(!navigator.clipboard||!window.ClipboardItem)throw Error('เบราว์เซอร์ไม่รองรับ Copy image — ใช้ Download');let promise=produce().then(f=>f.blob);await navigator.clipboard.write([new ClipboardItem({'image/png':promise})]);$('exportInfo').textContent='คัดลอกภาพแล้ว'}catch(e){$('exportInfo').textContent=e.message||'Copy ไม่สำเร็จ ใช้ Download แทน'}};
window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo()}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){let o=current();if(!o||o.locked||mode==='single'||o.kind==='logo'&&o.scope!=='canvas')return;e.preventDefault();remember();let n=e.shiftKey?10:1;o.x+=e.key==='ArrowRight'?n:e.key==='ArrowLeft'?-n:0;o.y+=e.key==='ArrowDown'?n:e.key==='ArrowUp'?-n:0;if(o.kind==='logo')o.anchored=false;sync()}});
// Pinch changes preview zoom only, without modifying artwork.
const touches=new Map();let pinch=null;C.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2){if(drag){let o=state.objects.find(x=>x.id===drag.id);if(o)Object.assign(o,drag.original);drag=null}let [a,b]=[...touches.values()];pinch={d:Math.hypot(a.x-b.x,a.y-b.y),z:zoom||C.clientWidth/(mode==='single'?640:state.w)};try{C.setPointerCapture(e.pointerId)}catch{}}});C.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinch&&touches.size===2){let [a,b]=[...touches.values()];zoom=clamp(pinch.z*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(pinch.d,1),.035,3);fitCanvas()}});for(let type of ['pointerup','pointercancel'])C.addEventListener(type,e=>{touches.delete(e.pointerId);if(touches.size<2)pinch=null});

// V2.1: Personal templates are independent of artwork and do not retain comment identities.
const templateStorageKey='sccomment-v21-templates', templateLayouts=['stack','horizontal','grid','stagger','overlap','free'];
let templateDB=null, templateStore={items:[],defaultId:null,auto:true};
function factoryTemplate(){const d=defaults();const basic={schema:'SCCommentTemplate',version:1,id:'factory',name:'Factory default',w:d.w,h:d.h,bg:d.bg,objects:[],spacing:d.spacing,layout:d.layout,cardDefaults:d.cardDefaults,exportDefaults:d.exportDefaults,lockBrand:true};try{return window.SC_COMMENT_FACTORY?validateTemplate(window.SC_COMMENT_FACTORY):basic}catch(e){return basic}}
function validateTemplate(t){if(!t||t.schema!=='SCCommentTemplate'||t.version!==1||typeof t.name!=='string'||!t.name.trim()||t.name.length>80||!Array.isArray(t.objects)||t.objects.some(o=>!['logo','image'].includes(o.kind)))throw Error('ไฟล์ Template ไม่ถูกต้อง');validateProject({version:2,w:t.w,h:t.h,bg:t.bg,objects:t.objects,spacing:t.spacing});let c=t.cardDefaults,e=t.exportDefaults;if(!templateLayouts.includes(t.layout)||!c||!['reply','normal'].includes(c.type)||!['light','dark'].includes(c.theme)||!['auto','abstract','initial','illustration','default'].includes(c.avatarStyle)||!Number.isInteger(c.fontSize)||c.fontSize<25||c.fontSize>62||![400,600,700].includes(c.fontWeight)||!e||!['png','transparent','jpg'].includes(e.type)||![1,2].includes(e.scale))throw Error('ค่าเริ่มต้น Template ไม่ถูกต้อง');let clean=clone(t);clean.id=typeof t.id==='string'&&t.id?t.id:uid();clean.objects.forEach(o=>{if(o.kind==='logo'&&o.scope==='one')o.target=''});return clean}
function getDefaultTemplate(){return templateStore.items.find(t=>t.id===templateStore.defaultId)||factoryTemplate()}
function readLocalTemplates(){try{return JSON.parse(localStorage.getItem(templateStorageKey)||'null')}catch{return null}}
function openTemplateDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('IndexedDB unavailable'));let req=indexedDB.open('SCCommentStudioTemplates',1);req.onupgradeneeded=()=>req.result.createObjectStore('settings');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('Storage blocked'))})}
function dbRead(){return new Promise((resolve,reject)=>{let r=templateDB.transaction('settings','readonly').objectStore('settings').get('library');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbWrite(value){return new Promise((resolve,reject)=>{let tx=templateDB.transaction('settings','readwrite');tx.objectStore('settings').put(value,'library');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage aborted'))})}
async function persistTemplates(next){if(templateDB){try{await dbWrite(next);templateStore=next;return}catch(e){throw Error('บันทึก IndexedDB ไม่สำเร็จ — Export template เป็นไฟล์สำรอง')}}try{localStorage.setItem(templateStorageKey,JSON.stringify(next));templateStore=next;if(templateDB){templateDB.close();templateDB=null}}catch(e){throw Error('ไม่สามารถบันทึกในเบราว์เซอร์ได้ — Export template เป็นไฟล์สำรอง')}}
function templateMessage(msg,error=false){$('templateStatus').textContent=msg;$('templateStatus').style.color=error?'#ffacac':'';status(msg,error)}
function templateList(selectId){let s=$('templateList'),old=selectId||s.value;s.replaceChildren(new Option('— Select template —',''));for(let t of templateStore.items)s.add(new Option(t.name+(t.id===templateStore.defaultId?' · Default':''),t.id));s.value=old;$('templateAuto').checked=templateStore.auto!==false}
function readTemplateForm(){return {layout:$('templateLayout').value,cardDefaults:{type:$('templateType').value,theme:$('templateTheme').value,avatarStyle:$('templateAvatar').value,fontSize:clamp(Math.round(num($('templateFont').value,43)),25,62),fontWeight:num($('templateWeight').value,700)},exportDefaults:{type:$('templateExport').value,scale:num($('templateScale').value,1)},lockBrand:$('templateLock').checked}}
function fillCardDefaults(c){$('templateType').value=c.type;$('templateTheme').value=c.theme;$('templateAvatar').value=c.avatarStyle;$('templateFont').value=c.fontSize;$('templateWeight').value=c.fontWeight}
function fillTemplateForm(){let d=defaults();$('templateName').value=state.templateName&&state.templateName!=='Factory default'?state.templateName:'SCWork Q&A';$('templateLayout').value=state.layout||d.layout;fillCardDefaults({...d.cardDefaults,...state.cardDefaults});$('templateExport').value=state.exportDefaults?.type||'png';$('templateScale').value=String(state.exportDefaults?.scale||1);$('templateLock').checked=state.lockBrand!==false;templateList(templateStore.defaultId);$('templateStatus').textContent='Default: '+getDefaultTemplate().name}
function captureTemplate(){let name=$('templateName').value.trim();if(!name)throw Error('กรุณาระบุชื่อ Template');let form=readTemplateForm();let same=templateStore.items.find(t=>t.name===name);return validateTemplate({schema:'SCCommentTemplate',version:1,id:same?.id||uid(),name,w:state.w,h:state.h,bg:clone(state.bg),objects:state.objects.filter(o=>o.kind!=='comment').map(o=>({...clone(o),locked:form.lockBrand||o.locked})),spacing:state.spacing,...form})}
function applyTemplate(raw,keepComments=true,record=true){let t=validateTemplate(raw), old=keepComments?clone(comments()):[];if(record)remember();let oldW=state.w,oldH=state.h;state={...defaults(),w:t.w,h:t.h,bg:clone(t.bg),objects:clone(t.objects),spacing:t.spacing,layout:t.layout,cardDefaults:clone(t.cardDefaults),exportDefaults:clone(t.exportDefaults),templateName:t.name,lockBrand:t.lockBrand!==false};let scale=Math.min(t.w/oldW,t.h/oldH);for(let o of old){o.x*=t.w/oldW;o.y*=t.h/oldH;o.w*=scale;o.h*=scale;state.objects.push(o)}for(let l of logos())if(l.scope==='one')l.target=old[0]?.id||'';anchoredLogos();selected=old.at(-1)?.id||null;selectMode('multi');if(old.length)arrange(t.layout,false);else sync();status('ใช้ Template: '+t.name)}
function adoptTemplateSettings(t){remember();state.layout=t.layout;state.cardDefaults=clone(t.cardDefaults);state.exportDefaults=clone(t.exportDefaults);state.templateName=t.name;state.lockBrand=t.lockBrand; if(t.lockBrand)state.objects.filter(o=>o.kind!=='comment').forEach(o=>o.locked=true);sync()}
function replaceTemplate(t){return [...templateStore.items.filter(o=>o.id!==t.id&&o.name!==t.name),t]}
async function saveCurrentTemplate(asDefault){let t=captureTemplate();let next={...templateStore,items:replaceTemplate(t),defaultId:asDefault?t.id:templateStore.defaultId,auto:$('templateAuto').checked};await persistTemplates(next);adoptTemplateSettings(t);templateList(t.id);templateMessage(asDefault?'บันทึก Default แล้ว — เปิดเว็บครั้งถัดไปจะใช้ตาม Auto load':'บันทึกใน Template library แล้ว')}
let templateBusy=false;function templateAction(id,fn){$(id).onclick=async()=>{if(templateBusy)return;templateBusy=true;try{await fn()}catch(e){templateMessage(e.message||'เกิดข้อผิดพลาด',true)}finally{templateBusy=false}}}
$('templateOpen').onclick=()=>{fillTemplateForm();$('templateDialog').showModal()};$('templateClose').onclick=()=>$('templateDialog').close();$('templateUseCard').onclick=()=>{let c=current();if(c?.kind!=='comment')c=comments()[0];if(!c){templateMessage('ยังไม่มีการ์ดคำถามให้คัดลอกสไตล์',true);return}fillCardDefaults(c);templateMessage('นำสไตล์การ์ดมาใช้แล้ว — กด Save เพื่อบันทึก')};
templateAction('templateSave',()=>saveCurrentTemplate(true));templateAction('templateSaveLibrary',()=>saveCurrentTemplate(false));
templateAction('templateLoad',()=>{let t=templateStore.items.find(t=>t.id===$('templateList').value);if(!t)throw Error('เลือก Template ก่อน');if(state.objects.length&&!confirm('ใช้ Template ที่เลือก? รูปและโลโก้ปัจจุบันจะถูกแทนที่ แต่เก็บคำถามเดิม (Undo ได้)'))return;applyTemplate(t,true);fillTemplateForm();$('templateList').value=t.id;templateMessage('ใช้ Template แล้ว')});
templateAction('templateSetDefault',async()=>{let id=$('templateList').value;if(!templateStore.items.some(t=>t.id===id))throw Error('เลือก Template ก่อน');await persistTemplates({...templateStore,defaultId:id,auto:$('templateAuto').checked});templateList(id);templateMessage('ตั้งเป็น Default สำหรับการเปิดเว็บครั้งถัดไปแล้ว')});
templateAction('templateDelete',async()=>{let id=$('templateList').value;if(!id)throw Error('เลือก Template ก่อน');if(!confirm('ลบ Template นี้จาก Library?'))return;await persistTemplates({...templateStore,items:templateStore.items.filter(t=>t.id!==id),defaultId:templateStore.defaultId===id?null:templateStore.defaultId});templateList();templateMessage('ลบ Template แล้ว')});
$('templateAuto').onchange=async()=>{if(templateBusy)return;try{await persistTemplates({...templateStore,auto:$('templateAuto').checked});templateMessage('บันทึก Auto load แล้ว')}catch(e){$('templateAuto').checked=templateStore.auto;templateMessage(e.message,true)}};
$('templateImport').onclick=()=>{$('templateFile').value='';$('templateFile').click()};$('templateFile').onchange=async()=>{let f=$('templateFile').files[0];if(!f)return;try{if(f.size>100*1024*1024)throw Error('ไฟล์เกิน 100 MB');let t=validateTemplate(JSON.parse(await f.text()));t.id=templateStore.items.find(x=>x.name===t.name)?.id||uid();await persistTemplates({...templateStore,items:replaceTemplate(t)});templateList(t.id);templateMessage('นำเข้าแล้ว — เลือก Apply หรือ Set default')}catch(e){templateMessage(e.message,true)}};
templateAction('templateExportFile',()=>{let t=captureTemplate();download(new Blob([JSON.stringify(t,null,2)],{type:'application/json'}),`SCComment_Template_${filename(t.name)}.json`);templateMessage('Export Template จากการตั้งค่าปัจจุบันแล้ว')});
templateAction('templateFactoryFile',()=>{let t=captureTemplate();let js='window.SC_COMMENT_FACTORY = '+JSON.stringify(t).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029')+';\n';download(new Blob([js],{type:'text/javascript'}),'factory-template.js');templateMessage('นำ factory-template.js ไปแทนไฟล์เดิมก่อน Deploy')});
templateAction('templateReset',async()=>{if(!confirm('คืนค่า Factory Default? คำถามปัจจุบันจะยังอยู่ แต่รูปและโลโก้จะถูกแทนที่ (Undo ได้)'))return;await persistTemplates({...templateStore,defaultId:null,auto:true});applyTemplate(factoryTemplate(),true);fillTemplateForm();templateMessage('คืนค่า Factory Default แล้ว')});
$('newContent').onclick=()=>{if(comments().length&&!confirm('ล้างคำถามทั้งหมด แต่เก็บโลโก้ รูปประกอบ และพื้นหลังไว้? (Undo ได้)'))return;remember();state.objects=state.objects.filter(o=>o.kind!=='comment');for(let l of logos())if(l.scope==='one')l.target='';$('batchText').value='';$('batchReal').checked=false;selected=null;selectMode('multi');status('พร้อมสร้างเนื้อหาใหม่ — รักษาเทมเพลตเดิม')};
async function startTemplates(){try{let saved;try{templateDB=await openTemplateDB();saved=await dbRead()}catch(e){templateDB=null}if(!saved)saved=readLocalTemplates();if(saved&&Array.isArray(saved.items)){let items=[];for(let t of saved.items)try{items.push(validateTemplate(t))}catch{}templateStore={items,defaultId:saved.defaultId||null,auto:saved.auto!==false}}if(templateStore.auto!==false)applyTemplate(getDefaultTemplate(),false,false);else applyTemplate(factoryTemplate(),false,false);templateList();}catch(e){status('โหลด Template ไม่สำเร็จ — ใช้ค่ามาตรฐาน',true)}finally{presetUI();sync();if(document.fonts)document.fonts.ready.then(()=>{comments().forEach(recalc);sync()})}}
new ResizeObserver(fitCanvas).observe(stage);sync();startTemplates();

// V2.1.1: Mobile/tablet workspace layout is a local UI preference, not project content.
(function mobileWorkspace(){
 const mq=matchMedia('(max-width:1050px), (max-width:1366px) and (pointer:coarse)');
 const workspace=document.querySelector('.workspace'),center=workspace.querySelector('.center'),pane=$('toolsPane'),handle=$('workspaceSplit');
 const key='sccomment.workspace.split.v1';let percent=55,gesture=null,raf=0,focusTimer=0;
 try{const raw=localStorage.getItem(key);if(raw!==null&&Number.isFinite(Number(raw)))percent=clamp(Number(raw),30,75)}catch{}
 function apply(v){percent=clamp(v,30,75);workspace.style.setProperty('--sc-split',percent+'%');handle.setAttribute('aria-valuenow',String(Math.round(percent)));handle.setAttribute('aria-valuetext',Math.round(percent)+'% Canvas');}
 function save(){try{localStorage.setItem(key,String(percent))}catch{}}
 function keepFieldVisible(){const a=document.activeElement;if(!mq.matches||!pane.contains(a)||!a.matches('input,textarea,select'))return;const r=a.getBoundingClientRect(),p=pane.getBoundingClientRect();if(r.bottom>p.bottom-12)pane.scrollTop+=r.bottom-p.bottom+12;else if(r.top<p.top+12)pane.scrollTop+=r.top-p.top-12;}
 function viewport(){cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{if(!mq.matches){document.body.style.removeProperty('--sc-viewport-height');return}const v=window.visualViewport;const height=v&&Math.abs(v.scale-1)<.02?v.height:window.innerHeight;document.body.style.setProperty('--sc-viewport-height',Math.round(height)+'px');if(Math.abs(window.scrollY)>0)window.scrollTo(0,0);clearTimeout(focusTimer);focusTimer=setTimeout(keepFieldVisible,90);});}
 apply(percent);viewport();window.addEventListener('resize',viewport,{passive:true});window.visualViewport?.addEventListener('resize',viewport,{passive:true});window.visualViewport?.addEventListener('scroll',viewport,{passive:true});if(mq.addEventListener)mq.addEventListener('change',viewport);else mq.addListener(viewport);
 pane.addEventListener('focusin',()=>{clearTimeout(focusTimer);focusTimer=setTimeout(keepFieldVisible,120)});
 handle.addEventListener('pointerdown',e=>{if(!mq.matches||e.button!==0)return;e.preventDefault();gesture={id:e.pointerId,y:e.clientY,start:center.getBoundingClientRect().height,base:Math.max(1,workspace.clientHeight)};handle.setPointerCapture(e.pointerId)});
 handle.addEventListener('pointermove',e=>{if(gesture?.id===e.pointerId){apply((gesture.start+e.clientY-gesture.y)/gesture.base*100);e.preventDefault()}});
 for(const t of ['pointerup','pointercancel','lostpointercapture'])handle.addEventListener(t,e=>{if(gesture?.id===e.pointerId){gesture=null;save()}});
 handle.addEventListener('keydown',e=>{const v={ArrowUp:percent-5,ArrowDown:percent+5,Home:30,End:75}[e.key];if(v!==undefined){e.preventDefault();apply(v);save()}});
 handle.addEventListener('dblclick',()=>{apply(55);save()});
})();


(function appearance(){const b=$('uiTheme'),root=document.documentElement,key='sccomment.ui.theme.v1';const sun='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/></svg>',moon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M20.7 14.4A9 9 0 0 1 9.6 3.3a9 9 0 1 0 11.1 11.1z"/></svg>';function set(d,save){root.dataset.ui=d?'dark':'light';b.innerHTML=d?sun:moon;b.setAttribute('aria-pressed',String(d));b.title=d?'Light mode':'Dark mode';b.setAttribute('aria-label',b.title);document.querySelector('meta[name=theme-color]').content=d?'#15181d':'#ffffff';if(save)try{localStorage.setItem(key,root.dataset.ui)}catch{}}set(root.dataset.ui==='dark',false);b.onclick=()=>set(root.dataset.ui!=='dark',true)})();

(function primaryEditor(){const mq=matchMedia('(max-width:1050px), (max-width:1366px) and (pointer:coarse)'),panel=$('commentPanel'),slot=$('mobileCommentSlot'),inspector=document.querySelector('.inspector');function move(){if(mq.matches){slot.hidden=false;if(panel.parentNode!==slot)slot.append(panel)}else{if(panel.parentNode!==inspector)inspector.insertBefore(panel,$('imagePanel'));slot.hidden=true}}move();if(mq.addEventListener)mq.addEventListener('change',move);else mq.addListener(move)})();
